	public void CallerCompatibilityAndSourceValidationKeepNativePriority( string hex, int mode, string conflict, int nativeCode, int nativeOffset, string code, int offset, string family ) {
		var source = Convert.FromHexString( hex );
		var native = Assert.Throws<PcrePatternException>( () => Reference( source, mode, true, conflict ) );
		Assert.Equal( nativeCode, (int)native.ErrorCode );
		Assert.EndsWith( $" at offset {nativeOffset}.", native.Message );
		var actual = PcreByteCompiler.Compile( source, Options( mode, true, conflict ) );
		Assert.Null( actual.Pattern );
		Assert.Equal( Enum.Parse<PcreByteDiagnosticCode>( code ), actual.Diagnostic?.Code );
		Assert.Equal( offset, actual.Diagnostic?.ByteOffset );
		if ( family.Length > 0 ) { Assert.Contains( family, actual.Diagnostic!.Message, StringComparison.OrdinalIgnoreCase ); }
	}

	[Theory]
	[InlineData( "a.b", "a\\.b", "612E62", 5, "0:3" )]
	[InlineData( "(*UTF)\\d", "\\(\\*UTF\\)\\\\d", "282A555446295C64", 5, "0:8" )]
	[InlineData( "K", "\\x{4B}", "E284AA", 9, "0:3" )]
	[InlineData( "I", "\\x{49}", "C4B1", 41, "0:2" )]
	[InlineData( "A.B", "A\\.B", "20412E4220", 69, "1:3" )]
	[InlineData( "A", "A", "410D0A", 385, "0:1" )]
	public void LiteralAndCanonicalNodesShareWorkCancellationAndOwnedState( string pattern, string canonical, string hex, int mode, string spans ) {
		var source = Encoding.UTF8.GetBytes( pattern );
		var subject = Convert.FromHexString( hex );
		var reference = Reference( source, mode, true );
		var canonicalReference = Reference( Encoding.UTF8.GetBytes( canonical ), mode, false );
		AssertNative( reference, subject, 0, spans );
		AssertNative( canonicalReference, subject, 0, spans );
		var steps = new List<int>();
		var canonicalSteps = new List<int>();
		var options = Options( mode, true ) with { WorkObserver = steps.Add };
		var compiled = Compile( source, options );
		Array.Fill( source, (byte)'x' );
		typeof( PcreByteOptions ).GetProperty( "Literal" )?.SetValue( options, false );
		typeof( PcreByteOptions ).GetProperty( "Caseless" )!.SetValue( options, false );
		typeof( PcreByteOptions ).GetProperty( "Utf8" )!.SetValue( options, false );
		Compare( reference, subject, 0, compiled.Match( subject ) );
		Compare( canonicalReference, subject, 0, Compile( Encoding.UTF8.GetBytes( canonical ), Options( mode, false ) with { WorkObserver = canonicalSteps.Add } ).Match( subject ) );
		Assert.Equal( canonicalSteps, steps );
		Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
		Assert.True( steps.Count > 2 );
		var limited = Compile( Encoding.UTF8.GetBytes( pattern ), Options( mode, true ) with { MatchWorkLimit = steps.Count - 1 } ).Match( subject );
		Assert.Null( limited.Match );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		using var cancellation = new CancellationTokenSource();
		var cancellable = Compile( Encoding.UTF8.GetBytes( pattern ), Options( mode, true ) with {
			WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } }
		} );
		Assert.Throws<OperationCanceledException>( () => cancellable.Match( subject, 0, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( source, Options( mode, true, "Ucp" ) with { MatchWorkLimit = 0 }, cancellation.Token ) );
		var invalid = PcreByteCompiler.Compile( new byte[] { 0xFF }, Options( mode, true, "Ucp" ) with { MatchWorkLimit = 0 } );
		Assert.Equal( PcreByteDiagnosticCode.InvalidWorkLimit, invalid.Diagnostic?.Code );
	}

	[Theory]
	[InlineData( 0 )]
	[InlineData( 1 )]
	[InlineData( 2 )]
	public void GrammarLookingTextConsumesNeitherCapturesNorParserDepth( int selection ) {
		var pattern = selection switch {
			0 => String.Concat( new string( '(', 257 ), "A", new string( ')', 257 ) ),
			1 => String.Concat( String.Concat( Enumerable.Repeat( "(?:", 257 ) ), "A", new string( ')', 257 ) ),
			_ => "a{4096}"
		};
		var source = Encoding.UTF8.GetBytes( pattern );
		var reference = Reference( source, 1, true );
		AssertNative( reference, source, 0, $"0:{source.Length}" );
		Compare( reference, source, 0, Compile( source, Options( 1, true ) ).Match( source ) );
	}

	[Fact]
	public void LiteralTextKeepsTheSharedCompiledInstructionCeiling() {
		var source = Encoding.ASCII.GetBytes( new string( 'A', 4096 ) );
		var reference = Reference( source, 0, true );
		AssertNative( reference, source, 0, "0:4096" );
		var actual = PcreByteCompiler.Compile( source, Options( 0, true ) );
		Assert.Null( actual.Pattern );
		Assert.Equal( PcreByteDiagnosticCode.PatternRepeatLimitExceeded, actual.Diagnostic?.Code );
	}

	[Fact]
	public void LiteralModeRetainsStrictSubjectAndStartOffsetValidation() {
		var compiled = Compile( @"\é"u8.ToArray(), Options( 1, true ) );
		var bad = compiled.Match( new byte[] { 0xFF } );
		Assert.Equal( PcreByteDiagnosticCode.InvalidUtf8Subject, bad.Diagnostic?.Code );
		Assert.Equal( 0, bad.Diagnostic?.ByteOffset );
		Assert.Null( bad.Match );
		var split = compiled.Match( "é"u8.ToArray(), 1 );
		Assert.Equal( PcreByteDiagnosticCode.InvalidStartOffset, split.Diagnostic?.Code );
		Assert.Null( split.Match );
		var outside = compiled.Match( "é"u8.ToArray(), 3 );
		Assert.Equal( PcreByteDiagnosticCode.InvalidStartOffset, outside.Diagnostic?.Code );
		Assert.Null( outside.Match );
	}

	private static PcreByteOptions Options( int mode, bool literal, string conflict = "" ) {
		var options = new PcreByteOptions {
			Utf8 = ( mode & 1 ) != 0, Ucp = ( mode & 2 ) != 0, MatchInvalidUtf = ( mode & 4 ) != 0,
			Caseless = ( mode & 8 ) != 0, CaselessRestricted = ( mode & 16 ) != 0, TurkishCasing = ( mode & 32 ) != 0,
			MatchWord = ( mode & 64 ) != 0, MatchLine = ( mode & 128 ) != 0,
			AnyCrLfNewline = ( mode & 256 ) != 0, BsrAnyCrLf = ( mode & 512 ) != 0
		};
		// Optional only for the tests-first build; every assertion still requires native literal behavior.
		typeof( PcreByteOptions ).GetProperty( "Literal" )?.SetValue( options, literal );
		if ( conflict.Length > 0 ) { typeof( PcreByteOptions ).GetProperty( conflict )!.SetValue( options, true ); }
		return options;
	}
	private static (uint Main, uint Extra) Conflict( string name ) => name switch {
		"AllowEmptyClass" => ( 1u, 0u ),
		"AltBsux" => ( 2u, 0u ),
		"DollarEndOnly" => ( 16u, 0u ),
		"DotAll" => ( 32u, 0u ),
		"DuplicateNames" => ( 64u, 0u ),
		"Extended" => ( 128u, 0u ),
		"MatchUnsetBackreference" => ( 512u, 0u ),
		"Multiline" => ( 1024u, 0u ),
		"NeverUcp" => ( 2048u, 0u ),
		"NeverUtf" => ( 4096u, 0u ),
		"NoAutoCapture" => ( 8192u, 0u ),
		"Ucp" => ( 131072u, 0u ),
		"Ungreedy" => ( 262144u, 0u ),
		"NeverBackslashC" => ( 1048576u, 0u ),
		"AltCircumflex" => ( 2097152u, 0u ),
		"AltVerbNames" => ( 4194304u, 0u ),
		"ExtendedMore" => ( 16777216u, 0u ),
		"AltExtendedClass" => ( 134217728u, 0u ),
		"AllowSurrogateEscapes" => ( 0u, 1u ),
		"BadEscapeIsLiteral" => ( 0u, 2u ),
		"EscapedCrIsLf" => ( 0u, 16u ),
		"ExtraAltBsux" => ( 0u, 32u ),
		"AllowLookaroundBackslashK" => ( 0u, 64u ),
		"AsciiBsD" => ( 0u, 256u ),
		"AsciiBsS" => ( 0u, 512u ),
		"AsciiBsW" => ( 0u, 1024u ),
		"AsciiPosix" => ( 0u, 2048u ),
		"AsciiDigit" => ( 0u, 4096u ),
		"PythonOctal" => ( 0u, 8192u ),
		"NoBackslashZero" => ( 0u, 16384u ),
		"NeverCallout" => ( 0u, 32768u ),
		_ => ( 0u, 0u )
	};
	private static PcreRegex8Bit Reference( byte[] source, int mode, bool literal, string conflict = "" ) {
		var selected = Conflict( conflict );
		return new( source, Encoding.UTF8, new PcreRegexSettings {
			Options = PcreOptions.Compiled | (PcreOptions)( selected.Main | ( literal ? 0x2000000u : 0u )
				| ( ( mode & 1 ) != 0 ? 0x80000u : 0u ) | ( ( mode & 2 ) != 0 ? 0x20000u : 0u )
				| ( ( mode & 4 ) != 0 ? 0x4000000u : 0u ) | ( ( mode & 8 ) != 0 ? 8u : 0u ) ),
			ExtraCompileOptions = (PcreExtraCompileOptions)( selected.Extra | ( ( mode & 16 ) != 0 ? 0x80u : 0u )
				| ( ( mode & 32 ) != 0 ? 0x10000u : 0u ) | ( ( mode & 64 ) != 0 ? 4u : 0u ) | ( ( mode & 128 ) != 0 ? 8u : 0u ) ),
			NewLine = (PcreNewLine)( ( mode & 256 ) != 0 ? 5 : 2 ),
			BackslashR = (PcreBackslashR)( ( mode & 512 ) != 0 ? 2 : 1 ), ParensLimit = 512
		} );
	}
	private static PcreCompiledBytePattern Compile( byte[] source, PcreByteOptions options ) {
		var actual = PcreByteCompiler.Compile( source, options );
		Assert.True( actual.IsSuccess, actual.Diagnostic?.Message );
		return Assert.IsType<PcreCompiledBytePattern>( actual.Pattern );
	}
	private static void AssertNative( PcreRegex8Bit reference, byte[] subject, int offset, string spans ) {
		var match = reference.Match( subject, offset );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		Assert.Empty( match.Mark.ToArray() );
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.EndIndex - capture.Index}" : "-" );
		}
	}
	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, actual.Diagnostic?.Message );
		Assert.Equal( expected.Success ? expected.Index : -1, actual.Match?.ByteIndex ?? -1 );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.EndIndex - expected.Index, actual.Match!.ByteLength );
		Assert.Equal( expected.Mark.ToArray(), actual.Match.MarkName.ToArray() );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.EndIndex - capture.Index ) : null, actual.Match.Captures[group] );
		}
	}
}
